<?php $pageTitle='Horários';$days=['Domingo','Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado']; ob_start(); ?>
<div class="page-heading"><div><span class="eyebrow">Disponibilidade recorrente</span><h1>Jornada de trabalho</h1><p>Cadastre mais de um período no mesmo dia para representar intervalos.</p></div></div>
<?php if(!$professionals):?><div class="panel empty"><i class="bi bi-person-x"></i><p>Cadastre um profissional antes de configurar horários.</p></div><?php else:?><div class="split"><section class="panel"><header class="panel-header"><h2>Novo período</h2></header><div class="panel-body"><form action="<?=e(url('/horarios'))?>" method="post" class="form-stack"><?=csrf_field()?><?php if(App\Core\Auth::role()!=='profissional'):?><label>Profissional<select name="profissional_id" required><?php foreach($professionals as $professional):?><option value="<?=e($professional['id'])?>" <?=selected($selected,$professional['id'])?>><?=e($professional['nome'])?></option><?php endforeach;?></select></label><?php else:?><input type="hidden" name="profissional_id" value="<?=e($selected)?>"><?php endif;?><label>Dia da semana<select name="dia_semana"><?php foreach($days as $key=>$day):?><option value="<?=e($key)?>"><?=e($day)?></option><?php endforeach;?></select></label><div class="form-grid"><label>Início<input type="time" name="hora_inicio" value="08:00" required></label><label>Fim<input type="time" name="hora_fim" value="12:00" required></label></div><button class="button primary" type="submit">Adicionar período</button></form></div></section>
<section class="panel"><header class="panel-header"><h2>Semana configurada</h2><?php if(App\Core\Auth::role()!=='profissional'):?><form method="get"><select name="profissional_id" onchange="this.form.submit()"><?php foreach($professionals as $professional):?><option value="<?=e($professional['id'])?>" <?=selected($selected,$professional['id'])?>><?=e($professional['nome'])?></option><?php endforeach;?></select></form><?php endif;?></header><div class="panel-body"><?php foreach($days as $dayNumber=>$day):$items=array_values(array_filter($periods,fn($period)=>(int)$period['dia_semana']===$dayNumber));?><div style="display:grid;grid-template-columns:140px 1fr;gap:14px;padding:13px 0;border-bottom:1px solid var(--border)"><strong><?=e($day)?></strong><div><?php if($items):?><?php foreach($items as $period):?><span class="badge" style="margin:0 5px 5px 0"><?=e(substr($period['hora_inicio'],0,5))?>–<?=e(substr($period['hora_fim'],0,5))?><form method="post" action="<?=e(url('/horarios/'.$period['id'].'/remover'))?>" style="display:inline" data-confirm="Remover este período?"><?=csrf_field()?><button class="icon-button" style="display:inline-grid;width:22px;height:22px" aria-label="Remover">×</button></form></span><?php endforeach;?><?php else:?><span class="subtle">Não atende</span><?php endif;?></div></div><?php endforeach;?></div></section></div><?php endif;?>
